// Signs release builds (APK and AAB) with the Play upload key when
// mobile/credentials/upload-key.properties exists; otherwise release builds
// keep the debug key, which is fine for test APKs but not for the Play Store.
// The key never enters git: create it with scripts/create-upload-key.sh.
// A config plugin because android/ is regenerated by `expo prebuild`.
const { withAppBuildGradle } = require("expo/config-plugins");

const MARKER = "// iodriven: upload-key signing";

const SIGNING_CONFIG = `
        ${MARKER}
        release {
            def props = new Properties()
            def propsFile = new File(rootProject.projectDir, "../credentials/upload-key.properties")
            if (propsFile.exists()) {
                propsFile.withInputStream { props.load(it) }
                storeFile new File(propsFile.parentFile, props["storeFile"])
                storePassword props["storePassword"]
                keyAlias props["keyAlias"]
                keyPassword props["keyPassword"]
            }
        }`;

module.exports = function withUploadSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents;
    if (gradle.includes(MARKER)) return cfg;
    gradle = gradle.replace(/signingConfigs \{/, (m) => `${m}${SIGNING_CONFIG}`);
    // In buildTypes.release only: the first `signingConfig signingConfigs.debug`
    // after `release {` inside buildTypes.
    const buildTypes = gradle.indexOf("buildTypes {");
    const release = gradle.indexOf("release {", buildTypes);
    const line = "signingConfig signingConfigs.debug";
    const at = gradle.indexOf(line, release);
    if (buildTypes < 0 || release < 0 || at < 0) {
      throw new Error("with-upload-signing: android/app/build.gradle changed shape; update the plugin.");
    }
    gradle =
      gradle.slice(0, at) +
      'signingConfig new File(rootProject.projectDir, "../credentials/upload-key.properties").exists() ? signingConfigs.release : signingConfigs.debug' +
      gradle.slice(at + line.length);
    cfg.modResults.contents = gradle;
    return cfg;
  });
};
